                border: `1px solid ${t("--color-border-default")}`,
                backgroundColor: "transparent",
                cursor: "pointer",
              }}
            >
              Light Mode
            </button>
            <button
              onClick={() => {}}
              style={{
                padding: "0.5rem 1rem",
                borderRadius: t("--radius-element"),
                border: `1px solid ${t("--color-border-default")}`,
                backgroundColor: "transparent",
                cursor: "pointer",
              }}
            >
              Dark Mode
            </button>
            <button
